#!/usr/bin/env python3
"""Check exact parity between the maintained sparse table and retired build rewrites."""
from pathlib import Path
import json

root = Path(__file__).resolve().parents[1]
upstream = (root / "vendor/sources/eden/src/common/sparse_large_vector.h").read_text()
active = (root / "vendor/encore-active/eden-core/src/common/sparse_large_vector.h").read_text()
cmake = (root / "headless/CMakeLists.txt").read_text()
selector = (root / "headless/inject.cmake").read_text()
pairs = json.loads(r'''[["AllocateMemoryPages(alloc_size)","AllocateSparsePages(alloc_size)",2],["FreeMemoryPages(base_ptr, alloc_size)","FreeSparsePages(base_ptr, alloc_size)",2],["mprotect(reinterpret_cast<void*>(page), HostPageSize, PROT_READ | PROT_WRITE)","CommitSparsePage(page)",1],["if (IsCommittedPage(start / sizeof(T))) {","if (IsCommittedPage(start)) {",1],["if (index > alloc_size / sizeof(T)) {","if (index >= alloc_size / sizeof(T)) {",3],["#include <atomic>\n","#include <atomic>\n#include <mutex>\n",1],["void ZeroRegion(std::size_t start, std::size_t end_) noexcept {","void ZeroRegion(std::size_t start, std::size_t end_) noexcept {\n        std::lock_guard<std::mutex> mutation_lock{sparse_mutation_mutex};",1],["void FreeMemoryPages(void* base, std::size_t size) noexcept;","void FreeMemoryPages(void* base, std::size_t size) noexcept;\nvoid* AllocateSparsePages(std::size_t size) noexcept;\nvoid FreeSparsePages(void* base, std::size_t size) noexcept;\nvoid CommitSparsePage(std::uintptr_t page) noexcept;\nvoid DecommitSparsePage(std::uintptr_t page) noexcept;\nstd::size_t SparseCommitSpan() noexcept;",1],["            std::memset(reinterpret_cast<void*>(page), 0, (std::min)( HostPageSize, end - page));","            const auto index = (page - reinterpret_cast<u64>(base_ptr)) / sizeof(T);\n            if (end - page >= HostPageSize) {\n                DecommitPage(index);\n            } else {\n                std::memset(reinterpret_cast<void*>(page), 0, end - page);\n            }",1],["    constexpr void CommitPage(std::size_t index) noexcept {\n        auto page_index = (index * sizeof(T)) >> HostPageBits;","    void DecommitPage(std::size_t index) noexcept {\n        const auto page_index = (index * sizeof(T)) >> HostPageBits;\n        const auto vector_base = reinterpret_cast<std::uintptr_t>(base_ptr);\n        const auto page_address = reinterpret_cast<std::uintptr_t>(base_ptr + index) & HostPageMask;\n        // A host page may be cleared while *other* pages in its 2 MiB\n        // physical slot remain in use. Clearing only the commit bitmap then\n        // retains stale PageEntryData in the still-writable private backing.\n        // CommitSparsePage does not re-zero an already owned slot, so remap\n        // would resurrect old CPU/GPU address translations. Also zero the\n        // dense fallback, where DecommitSparsePage intentionally does nothing.\n        // ZeroRegion holds sparse_mutation_mutex and only calls here for a\n        // committed/writable host page.\n        std::memset(reinterpret_cast<void*>(page_address), 0, HostPageSize);\n        committed_pages[page_index >> 6].fetch_and(~(1ULL << (page_index & 63)), std::memory_order_acq_rel);\n\n        const std::size_t span = SparseCommitSpan();\n        const std::size_t slot_offset = ((page_address - vector_base) / span) * span;\n        const std::size_t first_page = slot_offset / HostPageSize;\n        const std::size_t last_page = (std::min)(first_page + span / HostPageSize,\n                                                  (alloc_size + HostPageSize - 1) / HostPageSize);\n        for (std::size_t candidate = first_page; candidate < last_page; ++candidate) {\n            const auto bits = committed_pages[candidate >> 6].load(std::memory_order_acquire);\n            if ((bits >> (candidate & 63)) & 1) return;\n        }\n        DecommitSparsePage(vector_base + slot_offset);\n    }\n\n    void CommitPage(std::size_t index) noexcept {\n        std::lock_guard<std::mutex> mutation_lock{sparse_mutation_mutex};\n        if (IsCommittedPage(index)) return;\n        auto page_index = (index * sizeof(T)) >> HostPageBits;",1],["    std::size_t alloc_size{};","    std::mutex sparse_mutation_mutex;\n    std::size_t alloc_size{};",1]]''')
# The checked source retains every historical transformation and one
# additional half-open interval bounds guard for ZeroRegion.
pairs.append(("    void ZeroRegion(std::size_t start, std::size_t end_) noexcept {\n        std::lock_guard<std::mutex> mutation_lock{sparse_mutation_mutex};", "    void ZeroRegion(std::size_t start, std::size_t end_) noexcept {\n        // Callers normally provide a half-open in-bounds interval. Reject\n        // reversed/empty ranges and clip an oversized tail before constructing\n        // pointers, so untrusted guest extents cannot wrap into a huge memset.\n        const std::size_t limit = alloc_size / sizeof(T);\n        if (start >= end_ || start >= limit) return;\n        end_ = (std::min)(end_, limit);\n        std::lock_guard<std::mutex> mutation_lock{sparse_mutation_mutex};", 1))
for old, new, expected in pairs:
    assert upstream.count(old) == expected, ("pinned sparse origin changed", old[:80], expected)
    upstream = upstream.replace(old, new)
assert upstream == active, "maintained sparse source differs from former generated header"
assert 'configure_file("${EDEN_MAINTAINED_SPARSE_VECTOR}"' in cmake
assert 'write_derived("${PORT_BUILD_DIR}/sparse/common/sparse_large_vector.h"' not in cmake
assert "function(eden_sparse_replace" not in cmake
assert 'include_directories(BEFORE "${CMAKE_BINARY_DIR}/headless/sparse")' in selector
assert '${PORT_BUILD_DIR}/sparse/common/sparse_large_vector.h" COPYONLY' in cmake
print("MAINTAINED_SPARSE_VECTOR_PARITY_PASS: 12 verified rewrites, selected header overlay")
